#include <WiFi.h>
#include <WebServer.h>

// Smart Home Light Automation
// Hosts a tiny web page that toggles a relay over WiFi.

const char* WIFI_SSID = "YOUR_WIFI_NAME";
const char* WIFI_PASSWORD = "YOUR_WIFI_PASSWORD";

const int RELAY_PIN = 26;
bool lampOn = false;

WebServer server(80);

void setup() {
  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW);

  Serial.begin(115200);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Connected! Open this in a browser: http://");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.on("/on", handleOn);
  server.on("/off", handleOff);
  server.begin();
}

void loop() {
  server.handleClient();
}

void handleRoot() {
  String page = "<h1>Living Room Lamp</h1>";
  page += "<p>Status: ";
  page += lampOn ? "ON" : "OFF";
  page += "</p>";
  page += "<p><a href=\"/on\"><button>Turn ON</button></a> ";
  page += "<a href=\"/off\"><button>Turn OFF</button></a></p>";
  server.send(200, "text/html", page);
}

void handleOn() {
  lampOn = true;
  digitalWrite(RELAY_PIN, HIGH);
  server.sendHeader("Location", "/");
  server.send(303); // redirect back to the main page
}

void handleOff() {
  lampOn = false;
  digitalWrite(RELAY_PIN, LOW);
  server.sendHeader("Location", "/");
  server.send(303);
}
